item.aggregated_output:
        return _relative_path(Path(f), self.srcdir).as_posix()

    # copy downloadable files
    if self.env.dlfiles:
        ensuredir(self._downloads_dir)
        for src in status_iterator(
            self.env.dlfiles,
            __('copying downloadable files... '),
            'brown',
            len(self.env.dlfiles),
            self.config.verbosity,
            stringify_func=to_relpath,
        ):
            try:
                dest = self._downloads_dir / self.env.dlfiles[src][1]
                ensuredir(dest.parent)
                copyfile(self.srcdir / src, dest, force=True)
            except OSError as err:
                logger.warning(
                    __('cannot copy downloadable file %r: %s'),
                    self.srcdir / src,
                    err,
                )

def create_pygments_style_file(self) -> None:
    """Create a style file for pygments."""
    pyg_path = self._static_dir / 'pygments.css'
    with open(pyg_path, 'w', encoding='utf-8') as f:
        f.write(self.highlighter.get_stylesheet())

    if self.dark_highlighter:
        dark_path = self._static_dir / 'pygments_dark.css'
        with open(dark_path, 'w', encoding='utf-8') as f:
            f.write(self.dark_highlighter.get_stylesheet())

def copy_translation_js(self) -> None:
    """Copy a JavaScript file for translations."""
    if js_file := self._get_translations_js():
        copyfile(
            js_file,
            self._static_dir / 'translations.js',
            force=True,
        )

def copy_stemmer_js(self) -> None:
    """Copy a JavaScript file for stemmer."""
    if self.indexer is not None:
        if hasattr(self.indexer, 'get_js_stemmer_rawcodes'):
            for jsfile in self.indexer.get_js_stemmer_rawcodes():
                js_path = Path(jsfile)
                copyfile(
                    js_path,
                    self._static_dir / js_path.name,
                    force=True,
                )
        else:
            if js_stemmer_rawcode := self.indexer.get_js_stemmer_rawcode():
                copyfile(
                    js_stemmer_rawcode,
                    self._static_dir / '_stemmer.js',
                    force=True,
                )

def copy_theme_static_files(self, context: dict[str, Any]) -> None:
    def onerror(filename: str, error: Exception) -> None:
        msg = __("Failed to copy a file in the theme's 'static' directory: %s: %r")
        logger.warning(msg, filename, error)

    if self.theme:
        for entry in reversed(self.theme.get_theme_dirs()):
            copy_asset(
                Path(entry, 'static'),
                self._static_dir,
                excluded=DOTFILES,
                context=context,
                renderer=self.templates,
                onerror=onerror,
                force=True,
            )

def copy_html_static_files(self, context: dict[str, Any]) -> None:
    def onerror(filename: str, error: Exception) -> None:
        logger.warning(
            __('Failed to copy a file in html_static_file: %s: %r'), filename, error
        )

    excluded = Matcher([*self.config.exclude_patterns, '**/.*'])
    for entry in self.config.html_static_path:
        copy_asset(
            self.confdir / entry,
            self._static_dir,
            excluded=excluded,
            context=context,
            renderer=self.templates,
            onerror=onerror,
            force=True,
        )

def copy_html_logo(self) -> None:
    if self.config.html_logo and not is_url(self.config.html_logo):
        source_path = self.confdir / self.config.html_logo
        copyfile(
            source_path,
            self._static_dir / source_path.name,
            force=True,
        )

def copy_html_favicon(self) -> None:
    if self.config.html_favicon and not is_url(self.config.html_favicon):
        source_path = self.confdir / self.config.html_favicon
        copyfile(
            source_path,
            self._static_dir / source_path.name,
            force=True,
        )

def copy_static_files(self) -> None:
    try:
        with progress_message(__('copying static files'), nonl=False):
            # Ensure that the static directory exists
            self._static_dir.mkdir(parents=True, exist_ok=True)

            # prepare context for templates
            context = self.globalcontext.copy()
            if self.indexer is not None:
                context.update(self.indexer.context_for_searchtool())

            self.create_pygments_style_file()
            self.copy_translation_js()
            self.copy_stemmer_js()
            self.copy_theme_static_files(context)
            self.copy_html_static_files(context)
            self.copy_html_logo()
            self.copy_html_favicon()
    except OSError as err:
        logger.warning(__('cannot copy static file %r'), err)

def copy_extra_files(self) -> None:
    """Copy html_extra_path files."""
    try:
        with progress_message(__('copying extra files'), nonl=False):
            excluded = Matcher(self.config.exclude_patterns)
            for extra_path in self.config.html_extra_path:
                copy_asset(
                    self.confdir / extra_path,
                    self.outdir,
                    excluded=excluded,
                    force=True,
                )
    except OSError as err:
        logger.warning(__('cannot copy extra file %r'), err)

def write_buildinfo(self) -> None:
    try:
        self.build_info.dump(self.outdir / '.buildinfo')
    except OSError as exc:
        logger.warning(__('Failed to write build info file: %r'), exc)

def cleanup(self) -> None:
    # clean up theme stuff
    if self.theme:
        self.theme._cleanup()

def post_process_images(self, doctree: Node) -> None:
    """Pick the best candidate for an image and link down-scaled images to
    their high resolution version.
    """
    super().post_process_images(doctree)

    if self.config.html_scaled_image_link and self.html_scaled_image_link:
        for node in doctree.findall(nodes.image):
            if not any((key in node) for key in ('scale', 'width', 'height')):
                # resizing options are not given. scaled image link is available
                # only for resized images.
                continue
            if isinstance(node.parent, nodes.reference):
                # A image having hyperlink target
                continue
            if 'no-scaled-link' in node['classes']:
                # scaled image link is disabled for this node
                continue

            uri = node['uri']
            reference = nodes.reference('', '', internal=True)
            if uri in self.images:
                reference['refuri'] = posixpath.join(self.imgpath, self.images[uri])
            else:
                reference['refuri'] = uri
            node.replace_self(reference)
            reference.append(node)

def load_indexer(self, docnames: Set[str]) -> None:
    assert self.indexer is not None
    keep = set(self.env.all_docs).difference(docnames)
    try:
        search_index_path = self.outdir / self.searchindex_filename
        if self.indexer_dumps_unicode:
            with open(search_index_path, encoding='utf-8') as ft:
                self.indexer.load(ft, self.indexer_format)
        else:
            with open(search_index_path, 'rb') as fb:
                self.indexer.load(fb, self.indexer_format)
    except (OSError, ValueError):
        if keep:
            logger.warning(
                __(
                    "search index couldn't be loaded, but not all "
                    'documents will be built: the index will be '
                    'incomplete.'
                )
            )
    # delete all entries for files that will be rebuilt
    self.indexer.prune(keep)

def index_page(self, pagename: str, doctree: nodes.document, title: str) -> None:
    # only index pages with title
    if self.indexer is not None and title:
        filename = self.env.doc2path(pagename, base=False)
        metadata = self.env.metadata.get(pagename, {})
        if 'no-search' in metadata or 'nosearch' in metadata:
            self.indexer.feed(pagename, filename, '', new_document(''))
        else:
            self.indexer.feed(pagename, filename, title, doctree)

def _get_local_toctree(
    self, docname: str, collapse: bool = True, **kwargs: Any
) -> str:
    if 'includehidden' not in kwargs:
        kwargs['includehidden'] = False
    if kwargs.get('maxdepth') == '':  # NoQA: PLC1901
        kwargs.pop('maxdepth')
    toctree = global_toctree_for_doc(
        self.env, docname, self, tags=self.tags, collapse=collapse, **kwargs
    )
    return self.render_partial(toctree)['fragment']

def get_output_path(self, page_name: str, /) -> Path:
    return Path(self.outdir, page_name + self.out_suffix)

def get_outfilename(self, pagename: str) -> _StrPath:
    return _StrPath(self.get_output_path(pagename))

def _get_sidebars(self, pagename: str, /) -> tuple[str, ...]:
    matched = None

    # default sidebars settings for selected theme
    sidebars = self.theme.sidebar_templates

    # user sidebar settings
    html_sidebars = self.get_builder_config('sidebars', 'html')
    msg = __('page %s matches two patterns in html_sidebars: %r and %r')
    for pattern, pat_sidebars in html_sidebars.items():
        if patmatch(pagename, pattern):
            if matched and _has_wildcard(pattern):
                # warn if both patterns contain wildcards
                if _has_wildcard(matched):
                    logger.warning(msg, pagename, matched, pattern)
                # else the already matched pattern is more specific
                # than the present one, because it contains no wildcard
                continue
            matched = pattern
            sidebars = tuple(pat_sidebars)
    return sidebars

def add_sidebars(self, pagename: str, ctx: dict[str, Any]) -> None:
    ctx['sidebars'] = list(self._get_sidebars(pagename))

# --------- these are overwritten by the serialization builder

def get_target_uri(self, docname: str, typ: str | None = None) -> str:
    return quote(docname) + self.link_suffix

def handle_page(
    self,
    pagename: str,
    addctx: dict[str, Any],
    templatename: str = 'page.html',
    *,
    outfilename: Path | None = None,
    event_arg: Any = None,
) -> None:
    ctx = self.globalcontext.copy()
    # current_page_name is backwards compatibility
    ctx['pagename'] = ctx['current_page_name'] = pagename
    ctx['encoding'] = self.config.html_output_encoding
    default_baseuri = self.get_target_uri(pagename)
    # in the singlehtml builder, default_baseuri still contains an #anchor
    # part, which relative_uri doesn't really like...
    default_baseuri = default_baseuri.rsplit('#', 1)[0]

    if self.config.html_baseurl:
        ctx['pageurl'] = posixpath.join(
            self.config.html_baseurl, self.get_target_uri(pagename)
        )
    else:
        ctx['pageurl'] = None

    def pathto(
        otheruri: str,
        resource: bool = False,
        baseuri: str = default_baseuri,
    ) -> str:
        if resource and '://' in otheruri:
            # allow non-local resources given by scheme
            return otheruri
        elif not resource:
            otheruri = self.get_target_uri(otheruri)
        uri = relative_uri(baseuri, otheruri) or '#'
        if uri == '#' and not self.allow_sharp_as_current_path:
            uri = baseuri
        return uri

    ctx['pathto'] = pathto

    def hasdoc(name: str) -> bool:
        if name in self.env.all_docs:
            return True
        if name == 'search' and self.search:
            return True
        return name == 'genindex' and self.get_builder_config('use_index', 'html')

    ctx['hasdoc'] = hasdoc

    ctx['toctree'] = lambda **kwargs: self._get_local_toctree(pagename, **kwargs)
    ctx['sidebars'] = list(self._get_sidebars(pagename))
    ctx.update(addctx)

    # 'blah.html' should have content_root = './' not ''.
    ctx['content_root'] = (f'..{SEP}' * default_baseuri.count(SEP)) or f'.{SEP}'

    outdir = self.outdir

    def css_tag(css: _CascadingStyleSheet) -> str:
        attrs = [
            f'{key}="{html.escape(value, quote=True)}"'
            for key, value in css.attributes.items()
            if value is not None
        ]
        uri = pathto(os.fspath(css.filename), resource=True)
        # the EPUB format does not allow the use of query components
        # the Windows help compiler requires that css links
        # don't have a query component
        if self.name not in {'epub', 'htmlhelp'}:
            if checksum := _file_checksum(outdir, css.filename):
                uri += f'?v={checksum}'
        return f'<link {" ".join(sorted(attrs))} href="{uri}" />'

    ctx['css_tag'] = css_tag

    def js_tag(js: _JavaScript | str) -> str:
        if not isinstance(js, _JavaScript):
            # str value (old styled)
            return f'<script src="{pathto(js, resource=True)}"></script>'

        body = js.attributes.get('body', '')
        attrs = [
            f'{key}="{html.escape(value, quote=True)}"'
            for key, value in js.attributes.items()
            if key != 'body' and value is not None
        ]

        if not js.filename:
            if attrs:
                return f'<script {" ".join(sorted(attrs))}>{body}</script>'
            return f'<script>{body}</script>'

        js_filename_str = os.fspath(js.filename)
        uri = pathto(js_filename_str, resource=True)
        if 'MathJax.js?' in js_filename_str:
            # MathJax v2 reads a ``?config=...`` query parameter,
            # special case this and just skip adding the checksum.
            # https://docs.mathjax.org/en/v2.7-latest/configuration.html#considerations-for-using-combined-configuration-files
            # https://github.com/sphinx-doc/sphinx/issues/11658
            pass
        # the EPUB format does not allow the use of query components
        elif self.name != 'epub':
            if checksum := _file_checksum(outdir, js.filename):
                uri += f'?v={checksum}'
        if attrs:
            return f'<script {" ".join(sorted(attrs))} src="{uri}"></script>'
        return f'<script src="{uri}"></script>'

    ctx['js_tag'] = js_tag

    # revert _css_files and _js_files
    self._css_files[:] = self._orig_css_files
    self._js_files[:] = self._orig_js_files

    self.update_page_context(pagename, templatename, ctx, event_arg)
    if new_template := self.events.emit_firstresult(
        'html-page-context', pagename, templatename, ctx, event_arg
    ):
        templatename = new_template

    # sort JS/CSS before rendering HTML
    try:  # NoQA: SIM105
        # Convert script_files to list to support non-list script_files
        # See: https://github.com/sphinx-doc/sphinx/issues/8889
        ctx['script_files'] = sorted(
            ctx['script_files'], key=lambda js: js.priority

            netloc = urlsplit(uri).netloc
            with contextlib.suppress(KeyError):
                # Refresh rate limit.
                # When there are many links in the queue, workers are all stuck waiting
                # for responses, but the builder keeps queuing. Links in the queue may
                # have been queued before rate limits were discovered.
                next_check = self.rate_limits[netloc].next_check
            if next_check > time.time():
                # Sleep before putting message back in the queue to avoid
                # waking up other threads.
                time.sleep(QUEUE_POLL_SECS)
                self.wqueue.put(CheckRequest(next_check, hyperlink), False)
                self.wqueue.task_done()
                continue
            status, info, code = self._check(docname, uri, hyperlink)
            if status == _Status.RATE_LIMITED:
                logger.info(
                    darkgray('-rate limited-   ') + uri + darkgray(' | sleeping...')  # NoQA: G003
                )
            else:
                self.rqueue.put(CheckResult(uri, docname, lineno, status, info, code))
            self.wqueue.task_done()

    def _check(self, docname: str, uri: str, hyperlink: Hyperlink) -> _URIProperties:
        # check for various conditions without bothering the network

        for doc_matcher in self.documents_exclude:
            if doc_matcher.match(docname):
                info = (
                    f'{docname} matched {doc_matcher.pattern} from '
                    'linkcheck_exclude_documents'
                )
                return _Status.IGNORED, info, 0

        if len(uri) == 0 or uri.startswith(('#', 'mailto:', 'tel:')):
            return _Status.UNCHECKED, '', 0
        if not uri.startswith(('http:', 'https:')):
            if uri_re.match(uri):
                # Non-supported URI schemes (ex. ftp)
                return _Status.UNCHECKED, '', 0

            if (hyperlink.docpath.parent / uri).exists():
                return _Status.WORKING, '', 0
            return _Status.BROKEN, '', 0

        # need to actually check the URI
        status: _Status
        status, info, code = _Status.UNKNOWN, '', 0
        for _ in range(self.retries):
            status, info, code = self._check_uri(uri, hyperlink)
            if status != _Status.BROKEN:
                break

        return status, info, code

    def _retrieval_methods(
        self,
        check_anchors: bool,
        anchor: str,
    ) -> Iterator[tuple[Callable[..., Response], dict[str, bool]]]:
        if not check_anchors or not anchor:
            yield self._session.head, {'allow_redirects': True}
        yield self._session.get, {'stream': True}

    def _check_uri(self, uri: str, hyperlink: Hyperlink) -> _URIProperties:
        req_url, delimiter, anchor = uri.partition('#')
        if delimiter and anchor:
            for rex in self.anchors_ignore:
                if rex.match(anchor):
                    anchor = ''
                    break
            else:
                for rex in self.anchors_ignore_for_url:
                    if rex.match(req_url):
                        anchor = ''
                        break
            anchor = unquote(anchor)

        # handle non-ASCII URIs
        try:
            req_url.encode('ascii')
        except UnicodeError:
            req_url = encode_uri(req_url)

        # Get auth info, if any
        for pattern, auth_info in self.auth:  # NoQA: B007 (false positive)
            if pattern.match(uri):
                break
        else:
            auth_info = None

        # update request headers for the URL
        headers = _get_request_headers(uri, self.request_headers)

        # Linkcheck HTTP request logic:
        #
        # - Attempt HTTP HEAD before HTTP GET unless page content is required.
        # - Follow server-issued HTTP redirects.
        # - Respect server-issued HTTP 429 back-offs.
        error_message = ''
        status_code = -1
        response_url = retry_after = ''
        for retrieval_method, kwargs in self._retrieval_methods(
            self.check_anchors, anchor
        ):
            try:
                with retrieval_method(
                    url=req_url,
                    auth=auth_info,
                    headers=headers,
                    timeout=self.timeout,
                    **kwargs,
                    _user_agent=self.user_agent,
                    _tls_info=(self.tls_verify, self.tls_cacerts),
                ) as response:
                    if anchor and self.check_anchors and response.ok:
                        try:
                            found = contains_anchor(response, anchor)
                        except UnicodeDecodeError:
                            return (
                                _Status.IGNORED,
                                'unable to decode response content',
                                0,
                            )
                        if not found:
                            return (
                                _Status.BROKEN,
                                __("Anchor '%s' not found") % quote(anchor),
                                0,
                            )

                # Copy data we need from the (closed) response
                status_code = response.status_code
                redirect_status_code = (
                    response.history[-1].status_code if response.history else None
                )
                retry_after = response.headers.get('Retry-After', '')
                response_url = f'{response.url}'
                response.raise_for_status()
                del response
                break

            except RequestTimeout as err:
                return self._timeout_status, str(err), 0

            except SSLError as err:
                # SSL failure; report that the link is broken.
                return _Status.BROKEN, str(err), 0

            except (ConnectionError, TooManyRedirects) as err:
                # Servers drop the connection on HEAD requests, causing
                # ConnectionError.
                error_message = str(err)
                continue

            except requests._IgnoredRedirection as err:
                # A redirection to an ignored URI was attempted; report it appropriately
                return (
                    _Status.IGNORED,
                    f'ignored redirect: {err.destination}',
                    err.status_code,
                )

            except HTTPError as err:
                error_message = str(err)

                # Unauthorized: the client did not provide required credentials
                if status_code == 401:
                    if self._allow_unauthorized:
                        return _Status.WORKING, 'unauthorized', 0
                    else:
                        return _Status.BROKEN, 'unauthorized', 0

                # Rate limiting; back-off if allowed, or report failure otherwise
                if status_code == 429:
                    if next_check := self.limit_rate(response_url, retry_after):
                        self.wqueue.put(CheckRequest(next_check, hyperlink), False)
                        return _Status.RATE_LIMITED, '', 0
                    return _Status.BROKEN, error_message, 0

                # Don't claim success/failure during server-side outages
                if status_code == 503:
                    return _Status.IGNORED, 'service unavailable', 0

                # For most HTTP failures, continue attempting alternate retrieval methods
                continue

            except Exception as err:
                # Unhandled exception (intermittent or permanent); report that
                # the link is broken.
                return _Status.BROKEN, str(err), 0

        else:
            # All available retrieval methods have been exhausted; report
            # that the link is broken.
            return _Status.BROKEN, error_message, 0

        # Success; clear rate limits for the origin
        netloc = urlsplit(req_url).netloc
        self.rate_limits.pop(netloc, None)

        if (
            (response_url.rstrip('/') == req_url.rstrip('/'))
            or _allowed_redirect(req_url, response_url, self.allowed_redirects)
        ):  # fmt: skip
            return _Status.WORKING, '', 0
        elif redirect_status_code is not None:
            return _Status.REDIRECTED, response_url, redirect_status_code
        else:
            return _Status.REDIRECTED, response_url, 0

    def limit_rate(self, response_url: str, retry_after: str | None) -> float | None:
        delay = DEFAULT_DELAY
        next_check = None
        if retry_after:
            try:
                # Integer: time to wait before next attempt.
                delay = float(retry_after)
            except ValueError:
                try:
                    # An HTTP-date: time of next attempt.
                    next_check = rfc1123_to_epoch(retry_after)
                except (ValueError, TypeError):
                    # TypeError: Invalid date format.
                    # ValueError: Invalid date, e.g. Oct 52th.
                    pass
                else:
                    delay = next_check - time.time()
            else:
                next_check = time.time() + delay
        netloc = urlsplit(response_url).netloc
        if next_check is None:
            max_delay = self.rate_limit_timeout
            try:
                rate_limit = self.rate_limits[netloc]
            except KeyError:
                delay = DEFAULT_DELAY
            else:
                last_wait_time = rate_limit.delay
                delay = 2.0 * last_wait_time
                if delay > max_delay > last_wait_time:
                    delay = max_delay
            if delay > max_delay:
                return None
            next_check = time.time() + delay
        self.rate_limits[netloc] = RateLimit(delay, next_check)
        return next_check


def _get_request_headers(
    uri: str,
    request_headers: dict[str, dict[str, str]],
) -> dict[str, str]:
    url = urlsplit(uri)
    candidates = (
        f'{url.scheme}://{url.netloc}',
        f'{url.scheme}://{url.netloc}/',
        uri,
        '*',
    )

    for u in candidates:
        if u in request_headers:
            return {**DEFAULT_REQUEST_HEADERS, **request_headers[u]}
    return {}


def contains_anchor(response: Response, anchor: str) -> bool:
    """Determine if an anchor is contained within an HTTP response."""
    parser = AnchorCheckParser(anchor)
    # Read file in chunks. If we find a matching anchor, we break
    # the loop early in hopes not to have to download the whole thing.
    for chunk in response.iter_content(chunk_size=4096, decode_unicode=True):
        if isinstance(chunk, bytes):
            # requests failed to decode, manually try to decode it
            chunk = chunk.decode()

        parser.feed(chunk)
        if parser.found:
            break
    parser.close()
    return parser.found


class AnchorCheckParser(HTMLParser):
    """Specialised HTML parser that looks for a specific anchor."""

    def __init__(self, search_anchor: str) -> None:
        super().__init__()

        self.search_anchor = search_anchor
        self.found = False

    def handle_starttag(self, tag: Any, attrs: Any) -> None:
        for key, value in attrs:
            if key in {'id', 'name'} and value == self.search_anchor:
                self.found = True
                break


def _allowed_redirect(
    url: str, new_url: str, allowed_redirects: dict[re.Pattern[str], re.Pattern[str]]
) -> bool:
    if allowed_redirects is _SENTINEL_LAR:
        return False
    return any(
        from_url.match(url) and to_url.match(new_url)
        for from_url, to_url in allowed_redirects.items()
    )


class RateLimit(NamedTuple):
    delay: float
    next_check: float


def rewrite_github_anchor(app: Sphinx, uri: str) -> str | None:
    """Rewrite anchor name of the hyperlink to github.com

    The hyperlink anchors in github.com are dynamically generated.  This rewrites
    them before checking and makes them comparable.
    """
    parsed = urlparse(uri)
    if parsed.hostname == 'github.com' and parsed.fragment:
        prefixed = parsed.fragment.startswith('user-content-')
        if not prefixed:
            fragment = f'user-content-{parsed.fragment}'
            return urlunparse(parsed._replace(fragment=fragment))
    return None


def compile_linkcheck_allowed_redirects(app: Sphinx, config: Config) -> None:
    """Compile patterns to the regexp objects."""
    if config.linkcheck_allowed_redirects is _SENTINEL_LAR:
        return
    if not isinstance(config.linkcheck_allowed_redirects, dict):
        msg = __(
            f'Invalid value `{config.linkcheck_allowed_redirects!r}` in '
            'linkcheck_allowed_redirects. Expected a dictionary.'
        )
        raise ConfigError(msg)
    allowed_redirects = {}
    for url, pattern in config.linkcheck_allowed_redirects.items():
        try:
            allowed_redirects[re.compile(url)] = re.compile(pattern)
        except re.error as exc:
            logger.warning(
                __('Failed to compile regex in linkcheck_allowed_redirects: %r %s'),
                exc.pattern,
                exc.msg,
            )
    config.linkcheck_allowed_redirects = allowed_redirects


def setup(app: Sphinx) -> ExtensionMetadata:
    app.add_builder(CheckExternalLinksBuilder)
    app.add_post_transform(HyperlinkCollector)

    app.add_config_value('linkcheck_ignore', [], '', types=frozenset({list, tuple}))
    app.add_config_value(
        'linkcheck_exclude_documents', [], '', types=frozenset({list, tuple})
    )
    app.add_config_value(
        'linkcheck_allowed_redirects', _SENTINEL_LAR, '', types=frozenset({dict})
    )
    app.add_config_value('linkcheck_auth', [], '', types=frozenset({list, tuple}))
    app.add_config_value('linkcheck_request_headers', {}, '', types=frozenset({dict}))
    app.add_config_value('linkcheck_retries', 1, '', types=frozenset({int}))
    app.add_config_value('linkcheck_timeout', 30, '', types=frozenset({float, int}))
    app.add_config_value('linkcheck_workers', 5, '', types=frozenset({int}))
    app.add_config_value('linkcheck_anchors', True, '', types=frozenset({bool}))
    # Anchors starting with ! are ignored since they are
    # commonly used for dynamic pages
    app.add_config_value(
        'linkcheck_anchors_ignore', ['^!'], '', types=frozenset({list, tuple})
    )
    app.add_config_value(
        'linkcheck_anchors_ignore_for_url', (), '', types=frozenset({list, tuple})
    )
    app.add_config_value(
        'linkcheck_rate_limit_timeout', 300.0, '', types=frozenset({float, int})
    )
    app.add_config_value(
        'linkcheck_allow_unauthorized', False, '', types=frozenset({bool})
    )
    app.add_config_value(
        'linkcheck_report_timeouts_as_broken', False, '', types=frozenset({bool})
    )

    app.add_event('linkcheck-process-uri')

    # priority 900 to happen after ``check_confval_types()``
    app.connect('config-inited', compile_linkcheck_allowed_redirects, priority=900)

    # FIXME: Disable URL rewrite handler for github.com temporarily.
    # See: https://github.com/sphinx-doc/sphinx/issues/9435
    # app.connect('linkcheck-process-uri', rewrite_github_anchor)

    return {
        'version': 'builtin',
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }

    if valid_credentials:
        assert len(valid_credentials) == 2, 'expected a pair of strings as credentials'
        expected_token = b64encode(':'.join(valid_credentials).encode()).decode('utf-8')
        del valid_credentials

    def authenticated(
        method: Callable[[CustomHandler], None],
    ) -> Callable[[CustomHandler], None]:
        def method_if_authenticated(self: CustomHandler) -> None:
            if expected_token is None:
                return method(self)
            elif not self.headers['Authorization']:
                self.send_response(401, 'Unauthorized')
                self.end_headers()
            elif self.headers['Authorization'] == f'Basic {expected_token}':
                return method(self)
            else:
                self.send_response(403, 'Forbidden')
                self.send_header('Content-Length', '0')
                self.end_headers()
            return None

        return method_if_authenticated

    class CustomHandler(BaseHTTPRequestHandler):
        protocol_version = 'HTTP/1.1'

        @authenticated
        def do_HEAD(self):
            self.do_GET()

        @authenticated
        def do_GET(self):
            if success_criteria(self):
                self.send_response(200, 'OK')
                self.send_header('Content-Length', '0')
            else:
                self.send_response(400, 'Bad Request')
                self.send_header('Content-Length', '0')
            self.end_headers()

    return CustomHandler


